            "worker_analysis_metrics-aggregation_20260515T043938.log",
            "worker_analysis_metrics-consolidation_20260515T041953.log",
            "worker_monitor_live-metrics-check_20260515T043832.log",
            "worker_monitor_live-metrics-check_20260515T045604.log",
        ]
    }
}


def extract_metrics_from_string(s, exp_dir_pattern):
    """Extract (step, actor_loss) pairs from a string that may contain metrics.jsonl content."""
    results = []

    # Try to find JSON objects with step and actor_loss
    # The data may be at various levels of JSON escaping
    # Strategy: repeatedly unescape and search for JSON objects

    # First, check if this string mentions the experiment directory
    # We need to be careful about which experiment the data belongs to

    # Find all JSON-like objects with actor_loss
    # Pattern: {"step": NNN, ... "actor_loss": NNN, ...}
    # But the data may be escaped multiple times

    # Try multiple levels of unescaping
    texts = [s]
    for _ in range(5):
        new_texts = []
        for t in texts:
            try:
                unescaped = json.loads('"' + t + '"') if not t.startswith('"') else json.loads(t)
                if isinstance(unescaped, str) and unescaped != t:
                    new_texts.append(unescaped)
            except:
                pass
            # Also try replacing common escape sequences
            t2 = t.replace('\\\\n', '\n').replace('\\n', '\n').replace('\\"', '"').replace('\\\\', '\\')
            if t2 != t:
                new_texts.append(t2)
        texts.extend(new_texts)

    # Now search all text variants for JSON objects with actor_loss
    for text in texts:
        # Find JSON objects - look for {...}
        for match in re.finditer(r'\{[^{}]*"actor_loss"[^{}]*\}', text):
            try:
                obj = json.loads(match.group())
                if "step" in obj and "actor_loss" in obj:
                    results.append((int(obj["step"]), float(obj["actor_loss"])))
            except (json.JSONDecodeError, ValueError, KeyError):
                pass

    return results


def process_log_line(line_str, exp_dir_pattern):
    """Process a single JSONL log line and extract metrics for given experiment."""
    results = []

    try:
        log_entry = json.loads(line_str)
    except json.JSONDecodeError:
        return results

    # We're interested in user messages that contain tool results
    if log_entry.get("type") != "user":
        # Also check assistant messages that might have structured content
        if log_entry.get("type") == "assistant":
            msg = log_entry.get("message", {})
            content = msg.get("content", [])
            for item in content:
                if isinstance(item, dict) and item.get("type") == "text":
                    text = item.get("text", "")
                    if exp_dir_pattern in text and "actor_loss" in text:
                        results.extend(extract_metrics_from_string(text, exp_dir_pattern))
        return results

    msg = log_entry.get("message", {})
    content = msg.get("content", [])

    # Also check tool_use_result field
    tool_result = log_entry.get("tool_use_result", {})
    if tool_result:
        structured = tool_result.get("structuredContent", {})
        if structured:
            result_str = structured.get("result", "")
            if isinstance(result_str, str) and exp_dir_pattern in result_str and "actor_loss" in result_str:
                results.extend(extract_metrics_from_deeply_nested(result_str, exp_dir_pattern))
        content_str = tool_result.get("content", "")
        if isinstance(content_str, str) and exp_dir_pattern in content_str and "actor_loss" in content_str:
            results.extend(extract_metrics_from_deeply_nested(content_str, exp_dir_pattern))

    for item in content:
        if not isinstance(item, dict):
            continue
        if item.get("type") != "tool_result":
            continue

        item_content = item.get("content", "")
        if isinstance(item_content, str) and "actor_loss" in item_content:
            # Check if this content is related to our experiment
            if exp_dir_pattern in item_content:
                results.extend(extract_metrics_from_deeply_nested(item_content, exp_dir_pattern))
            elif exp_dir_pattern not in item_content:
                # Could be metrics without explicit experiment directory reference
                # Only use if we're looking at an experiment-specific log
                pass
        elif isinstance(item_content, list):
            for sub in item_content:
                if isinstance(sub, dict):
                    text = sub.get("text", "")
                    if isinstance(text, str) and "actor_loss" in text and exp_dir_pattern in text:
                        results.extend(extract_metrics_from_deeply_nested(text, exp_dir_pattern))

    return results


def extract_metrics_from_deeply_nested(s, exp_dir_pattern):
    """Extract metrics from a deeply nested/escaped JSON string."""
    results = []

    # Progressive unescaping
    current = s
    all_texts = [current]

    for _ in range(10):
        # Try JSON string unescaping
        try:
            if current.startswith('"'):
                unescaped = json.loads(current)
            else:
                unescaped = json.loads('"' + current + '"')
            if isinstance(unescaped, str) and unescaped != current:
                current = unescaped
                all_texts.append(current)
                continue
        except:
            pass

        # Try parsing as JSON object
        try:
            obj = json.loads(current)
            if isinstance(obj, dict):
                # Check for result -> data -> stdout chain
                if "result" in obj:
                    inner = obj["result"]
                    if isinstance(inner, str):
                        current = inner
                        all_texts.append(current)
                        continue
                if "data" in obj:
                    data = obj["data"]
                    if isinstance(data, dict) and "stdout" in data:
                        current = data["stdout"]
                        all_texts.append(current)
                        continue
                if "stdout" in obj:
                    current = obj["stdout"]
                    all_texts.append(current)
                    continue
                # Direct metric object
                if "step" in obj and "actor_loss" in obj:
                    results.append((int(obj["step"]), float(obj["actor_loss"])))
                    break
            elif isinstance(obj, str):
                current = obj
                all_texts.append(current)
                continue
        except:
            pass

        # Manual unescape
        new = current.replace('\\\\n', '\n').replace('\\n', '\n').replace('\\"', '"').replace('\\\\', '\\')
        if new != current:
            current = new
            all_texts.append(current)
        else:
            break

    # Now search all accumulated texts for metric JSON objects
    for text in all_texts:
        # Split by newlines and try each line
        for line in text.split('\n'):
            line = line.strip()
            if not line or 'actor_loss' not in line:
                continue
            try:
                obj = json.loads(line)
                if isinstance(obj, dict) and "step" in obj and "actor_loss" in obj:
                    results.append((int(obj["step"]), float(obj["actor_loss"])))
            except:
                pass

        # Also try regex extraction as fallback
        for match in re.finditer(r'\{[^{}]*?"step"\s*:\s*(\d+)[^{}]*?"actor_loss"\s*:\s*(-?[\d.eE+-]+)[^{}]*?\}', text):
            try:
                step = int(match.group(1))
                actor_loss = float(match.group(2))
                results.append((step, actor_loss))
            except:
                pass
        # Try reverse order too (actor_loss before step)
        for match in re.finditer(r'\{[^{}]*?"actor_loss"\s*:\s*(-?[\d.eE+-]+)[^{}]*?"step"\s*:\s*(\d+)[^{}]*?\}', text):
            try:
                step = int(match.group(2))
                actor_loss = float(match.group(1))
                results.append((step, actor_loss))
            except:
                pass

    return results


def process_log_file_for_exp(log_path, exp_dir_pattern):
    """Process entire log file for a specific experiment."""
    results = []

    if not os.path.exists(log_path):
        return results

    with open(log_path, 'r', errors='replace') as f:
        for line_num, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            if exp_dir_pattern not in line and 'actor_loss' not in line:
                continue
            if exp_dir_pattern in line and 'actor_loss' in line:
                pairs = process_log_line(line, exp_dir_pattern)
                results.extend(pairs)

    return results


def process_tool_result_file(file_path, exp_dir_pattern):
    """Process the large tool result file."""
    results = []
    if not os.path.exists(file_path):
        return results

    with open(file_path, 'r', errors='replace') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            if 'actor_loss' not in line:
                continue
            if exp_dir_pattern in line:
                results.extend(extract_metrics_from_deeply_nested(line, exp_dir_pattern))
                # Also try the line as a whole
                results.extend(process_log_line(line, exp_dir_pattern))

    return results


def main():
    all_results = {}

    for exp_name, config in EXPERIMENTS.items():
        exp_dir_pattern = config["exp_dir_pattern"]
        all_pairs = []

        # Process log files
        for log_file in config["log_files"]:
            log_path = os.path.join(LOGS_DIR, log_file)
            pairs = process_log_file_for_exp(log_path, exp_dir_pattern)
            if pairs:
                print(f"  {exp_name}: Found {len(pairs)} pairs in {log_file}", file=sys.stderr)
            all_pairs.extend(pairs)

        # Also process the large tool result file for 009b
        if exp_name == "009b_s2":
            pairs = process_tool_result_file(TOOL_RESULT_FILE, exp_dir_pattern)
            if pairs:
                print(f"  {exp_name}: Found {len(pairs)} pairs in tool result file", file=sys.stderr)
            all_pairs.extend(pairs)

        # Deduplicate: keep last seen value for each step
        step_map = {}
        for step, actor_loss in all_pairs:
            step_map[step] = actor_loss

        if step_map:
            sorted_steps = sorted(step_map.keys())
            all_results[exp_name] = {
                "steps": sorted_steps,
                "actor_loss": [step_map[s] for s in sorted_steps]
            }
            print(f"{exp_name}: {len(sorted_steps)} unique steps, range [{sorted_steps[0]}, {sorted_steps[-1]}]", file=sys.stderr)
        else:
            all_results[exp_name] = None
            print(f"{exp_name}: NO DATA FOUND", file=sys.stderr)

    # Output JSON
    print(json.dumps(all_results, indent=2))


if __name__ == "__main__":
    main()
